import re

LEVEL = {"jr": "junior", "junior": "junior", "sr": "senior",
         "senior": "senior", "staff": "staff", "lead": "lead",
         "principal": "principal", "partner": "partner"}
NUMERAL = {"i": 1, "ii": 2, "iii": 3, "iv": 4}
ROLE = ("head of", "director of", "vp of", "vice president of")
ABBR = {"swe": "software engineer"}

def parse(title):
    s = re.sub(r"[^\w\s,]", " ", title.casefold())
    s = s.split(",")[0].strip()
    s = " ".join(ABBR.get(t, t) for t in s.split())
    if s.startswith(ROLE):
        return {"core": s, "level": None, "num": None}
    toks = s.split()
    num = NUMERAL.get(toks[-1]) if len(toks) > 1 else None
    if num:
        toks = toks[:-1]
    level = None
    while toks and toks[0] in LEVEL:
        level = LEVEL[toks.pop(0)]
    if not toks:
        return {"core": level, "level": None, "num": num}
    return {"core": " ".join(toks), "level": level, "num": num}
